CREATE TABLE pais (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, eliminado BOOLEAN NOT NULL DEFAULT FALSE, version BIGINT NOT NULL DEFAULT 0,nombre VARCHAR(150) NOT NULL);
CREATE UNIQUE INDEX ux_pais_nombre ON pais(lower(btrim(nombre))) WHERE eliminado=false;
CREATE TABLE provincia (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, eliminado BOOLEAN NOT NULL DEFAULT FALSE, version BIGINT NOT NULL DEFAULT 0,nombre VARCHAR(150) NOT NULL, pais_id BIGINT NOT NULL REFERENCES pais(id));
CREATE INDEX ix_provincia_pais ON provincia(pais_id);
CREATE UNIQUE INDEX ux_provincia_nombre ON provincia(lower(btrim(nombre)), pais_id) WHERE eliminado=false;
CREATE TABLE departamento (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, eliminado BOOLEAN NOT NULL DEFAULT FALSE, version BIGINT NOT NULL DEFAULT 0,nombre VARCHAR(150) NOT NULL, provincia_id BIGINT NOT NULL REFERENCES provincia(id));
CREATE INDEX ix_departamento_provincia ON departamento(provincia_id);
CREATE UNIQUE INDEX ux_departamento_nombre ON departamento(lower(btrim(nombre)), provincia_id) WHERE eliminado=false;
CREATE TABLE localidad (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, eliminado BOOLEAN NOT NULL DEFAULT FALSE, version BIGINT NOT NULL DEFAULT 0,nombre VARCHAR(150) NOT NULL,codigo_postal VARCHAR(150) NOT NULL, departamento_id BIGINT NOT NULL REFERENCES departamento(id));
CREATE INDEX ix_localidad_departamento ON localidad(departamento_id);
CREATE UNIQUE INDEX ux_localidad_nombre ON localidad(lower(btrim(nombre)), departamento_id) WHERE eliminado=false;
CREATE TABLE direccion (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, eliminado BOOLEAN NOT NULL DEFAULT FALSE, version BIGINT NOT NULL DEFAULT 0,calle VARCHAR(150) NOT NULL,numeracion VARCHAR(150) NOT NULL,barrio VARCHAR(150),manzana_piso VARCHAR(150),casa_departamento VARCHAR(150),referencia VARCHAR(500), localidad_id BIGINT NOT NULL REFERENCES localidad(id));
CREATE INDEX ix_direccion_localidad ON direccion(localidad_id);
CREATE TABLE persona (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, eliminado BOOLEAN NOT NULL DEFAULT FALSE, version BIGINT NOT NULL DEFAULT 0,nombre VARCHAR(150) NOT NULL,apellido VARCHAR(150) NOT NULL, direccion_id BIGINT NOT NULL REFERENCES direccion(id));
CREATE INDEX ix_persona_direccion ON persona(direccion_id);
CREATE TABLE usuario (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, email VARCHAR(254) NOT NULL UNIQUE, password_hash VARCHAR(255), rol VARCHAR(255) NOT NULL, proveedor_autenticacion VARCHAR(255) NOT NULL, proveedor_id VARCHAR(255), persona_id BIGINT REFERENCES persona(id), activo BOOLEAN NOT NULL DEFAULT TRUE, credential_version BIGINT NOT NULL DEFAULT 0, version BIGINT NOT NULL DEFAULT 0);
CREATE UNIQUE INDEX ux_usuario_provider ON usuario(proveedor_autenticacion,proveedor_id) WHERE proveedor_id IS NOT NULL;
CREATE INDEX ix_usuario_persona ON usuario(persona_id);
CREATE INDEX ix_persona_apellido ON persona(lower(apellido));
CREATE INDEX ix_localidad_postal ON localidad(codigo_postal);
CREATE INDEX ix_direccion_calle ON direccion(lower(calle),numeracion);
